//
// Centralizes JSON response encoding + structured error envelopes
// so every translated controller writes through one place. Matches
// the contract the translator's prompt_prelude.md declares.
package httpx

import (
	"encoding/json"
	"errors"
	"log"
	"net/http"
)

// ErrorResponse is the canonical structured error envelope.
// Code is a stable machine token (e.g. "BAD_JSON", "NOT_FOUND");
// Message is human-readable. Never leak server-side internals.
type ErrorResponse struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

// WriteJSON serializes payload as JSON and writes it with status.
func WriteJSON(w http.ResponseWriter, status int, payload any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	if payload == nil {
		return
	}
	if err := json.NewEncoder(w).Encode(payload); err != nil {
		log.Printf("httpx: encode failed: %v", err)
	}
}

// WriteError emits a structured error envelope at the given status.
func WriteError(w http.ResponseWriter, status int, code, message string) {
	WriteJSON(w, status, ErrorResponse{Code: code, Message: message})
}

// WriteValidationError emits a 422 with VALIDATION_ERROR + message.
// Accepts any error (typically from a DTO.Validate() call).
func WriteValidationError(w http.ResponseWriter, err error) {
	msg := "validation failed"
	if err != nil {
		msg = err.Error()
	}
	WriteError(w, http.StatusUnprocessableEntity, "VALIDATION_ERROR", msg)
}

// WriteInternal logs the cause and emits a 500 INTERNAL_ERROR.
// Never leaks the underlying error message to the client.
func WriteInternal(w http.ResponseWriter, r *http.Request, err error) {
	if err == nil {
		err = errors.New("unknown internal error")
	}
	log.Printf("httpx: 500 %s %s: %v", r.Method, r.URL.Path, err)
	WriteError(w, http.StatusInternalServerError, "INTERNAL_ERROR", "internal server error")
}
